preConditionHook:
// ARM THE SWING TRAIL ONLY AFTER A RETEST AND A NEW EXTREME. Until the trade has
// both pulled back into the area of the signal bar and afterwards gone on to a
// new extreme, the wider initial stop (a separate placement) stands alone, so the
// normal pullbacks of a tight channel cannot trap the trade out.
//
// The armed-trail recast again (see TrailArmedAfterProfitThreshold): T23-11
// states a GATE, and the pane system cannot express one exit conditioning
// another, since exits are ORed. Same arming idea as
// BreakevenStopOnSecondEntryTest, which arms a BREAKEVEN stop off a
// touch-recover-touch sequence at the ENTRY price; this one arms a SWING trail
// off a retest of the SIGNAL BAR followed by a new extreme, so the two arm on
// different bars and take the trade off at different levels.
//
// THE SIGNAL BAR IS CAPTURED ON THE FILL BAR as high[1]/low[1], the convention
// StopAtSignalBarRangeMultiple and StopFractionOfSignalBarRisk use -- NOT
// re-indexed by the position's age as the merged pseudocode's
// high[BarsSinceEntry + 1] would, which would make "reaches back" the length of
// the longest trade. The reset is on ctx.BarsSinceEntry() == 0, VERIFIED as 0 on
// the fill bar and as restarting through a reversal, never on a
// ctx.MarketPosition() == 0 test, which a reversal never passes through.
//
// THE RETEST CANNOT BE SUPPLIED BY THE FILL BAR ITSELF. The fill is at the bar's
// open, immediately after the signal bar, so that bar's low is inside the signal
// bar's area by construction and would hand the arming away for nothing; the
// retest test is therefore gated on ctx.BarsSinceEntry() >= 1. The new extreme
// must come AFTER the retest and must beat the running extreme since entry, which
// is seeded on the fill bar and updated after the tests so a bar cannot beat
// itself.
//
// "The area of the signal bar" is quantified as a fraction of ATR because Brooks
// gives no number; T23-11's own 0.25 is kept.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: AtrProfitTarget's and SwingPointTestHolds's block verbatim, including the
// TWO separate accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently. It re-seeds when the length changes, which is
// what makes it walkforward safe.
//
// THE PIVOT SCAN IS INLINED from SwingHigh per the B-list decision, at
// Occurrence 1. MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min):
// at-or-beyond the pivotStrength OLDER bars, STRICTLY beyond the pivotStrength
// NEWER bars (bars-ago indexing makes the SMALLER index the NEWER bar, so the
// strict half is the pk < pj loop); lag exactly pivotStrength bars, never 0 or 1;
// lookbackBars is EL's Length, offsets 0..lookbackBars-1 inclusive, the
// neighbourhood test reaching pivotStrength bars PAST the window; the -1 SENTINEL
// guarded because -1 as a PRICE sits under every real price; el_lt/el_le/el_gt/
// el_ge for the 2.22e-12 relational tolerance. No WFSafe_SwingLow exists, so
// plain EL governs. Every block runs unconditionally each bar so Max Bars Back
// covers it and the EasyLanguage call sites advance on the same bars.
//
// lookbackBars is not in the merged parameter list and is what makes the pivot
// window addressable; 40 is the corpus default. Ticks: MinMove/PriceScale are
// VERIFIED and the tick is written division-first into a local.
//
// Every scratch value is a localVariables entry, never a hook-scope declaration,
// so the hooks survive a double placement.
//
// Deepest bar touched: max(lookbackBars - 1 + pivotStrength, atrLookback + 1).
tickSize = ctx.MinMove() / ctx.PriceScale();
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
lo1 = -1.0;
for (pj = (int)pivotStrength; pj <= (int)lookbackBars - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)pivotStrength; pk < pj; ++pk) {
        if (!el_lt(low[pj], low[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)pivotStrength; ++pk) {
            if (!el_le(low[pj], low[pk])) { pok = false; break; }
        }
    }
    if (pok) { lo1 = low[pj]; break; }
}
hi1 = -1.0;
for (pj = (int)pivotStrength; pj <= (int)lookbackBars - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)pivotStrength; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)pivotStrength; ++pk) {
            if (!el_ge(high[pj], high[pk])) { pok = false; break; }
        }
    }
    if (pok) { hi1 = high[pj]; break; }
}
if (ctx.BarsSinceEntry() == 0) {
    sigHigh = high[1];
    sigLow = low[1];
    retestedLong = false;
    retestedShort = false;
    armedLong = false;
    armedShort = false;
    runHigh = high[0];
    runLow = low[0];
}
if (ctx.BarsSinceEntry() >= 1 && el_le(low[0], sigHigh + signalBarAreaAtr * atrValue)) retestedLong = true;
if (ctx.BarsSinceEntry() >= 1 && el_ge(high[0], sigLow - signalBarAreaAtr * atrValue)) retestedShort = true;
if (retestedLong && el_gt(high[0], runHigh)) armedLong = true;
if (retestedShort && el_lt(low[0], runLow)) armedShort = true;
if (el_gt(high[0], runHigh)) runHigh = high[0];
if (el_lt(low[0], runLow)) runLow = low[0];
